mapper.select:
select id, name, phone, address, remarks, create_time
  from fabric_supplier
 where id = #{id}

mapper.update:
update fabric_supplier
   set name = #{name},
       phone = #{phone},
       address = #{address},
       remarks = #{remarks}
 where id = #{id}

mapper.select:
select count(*)
  from fabric
 where supplier_id = #{supplierId}

select id, parent_id, name, category_level, sort_order
  from fabric_category
 where id = #{id}

select id, parent_id, name, category_level, sort_order
  from fabric_category
 where lower(name) = lower(#{name})
   and (
        (#{parentId} is null and parent_id is null)
        or parent_id = #{parentId}
   )

   and id != #{excludeId}

 limit 1

mapper.insert:
insert into fabric_category (
    parent_id, name, category_level, sort_order
) values (
    #{parentId}, #{name}, #{level}, #{sortOrder}
)

mapper.update:
update fabric_category
   set parent_id = #{parentId},
       name = #{name},
       category_level = #{level},
       sort_order = #{sortOrder}
 where id = #{id}

mapper.select:
select count(*)
  from fabric
 where category_id = #{categoryId}

mapper.update:
update fabric_code_sequence
   set last_value = last_value + 1
 where fabric_year = #{year}

update fabric_code_sequence
   set last_value = last_value + #{amount}
 where fabric_year = #{year}

mapper.select:
select last_value
  from fabric_code_sequence
 where fabric_year = #{year}

select fc.id, fc.fabric_id, fc.component_code, fct.name_cn as component_name_cn, fct.name_en as component_name_en, fc.percentage, fc.sort_order from fabric_composition fc left join fabric_component_type fct on fct.code = fc.component_code where fc.fabric_id in
#{fabricId}
order by fc.fabric_id, fc.sort_order, fc.id

mapper.insert:
insert into fabric_composition (
    fabric_id, component_code, percentage, sort_order
) values (
    #{fabricId}, #{componentCode}, #{percentage}, #{sortOrder}
)

mapper.select:
select id, fabric_id, image_url, thumbnail_url, image_type, sort_order, create_time from fabric_image where fabric_id in
#{fabricId}
order by fabric_id, sort_order, id

mapper.insert:
insert into fabric_image (
    fabric_id, image_url, thumbnail_url, image_type, sort_order, create_time
) values (
    #{fabricId}, #{imageUrl}, #{thumbnailUrl}, #{imageType}, #{sortOrder}, current_timestamp
)
